// Señales de juguete: quien lee una señal queda anotado como suscriptor
let efectoActual = null;

function senal(valor) {
  const suscriptores = new Set();
  return {
    leer() {
      if (efectoActual) suscriptores.add(efectoActual); // «me anoto»
      return valor;
    },
    escribir(nuevo) {
      if (nuevo === valor) return;                      // nada cambió: nadie se entera
      valor = nuevo;
      [...suscriptores].forEach((e) => e());            // avisa solo a los anotados
    },
  };
}

function efecto(fn) {
  const ejecutar = () => {
    const anterior = efectoActual;
    efectoActual = ejecutar;
    try { fn(); } finally { efectoActual = anterior; }
  };
  ejecutar();
}

